import type { Request, Response } from "express";
import { catchAsync } from "../../utils/catchAsync";
import { sendResponse } from "../../utils/sendResponse";
import { NotificationService } from "./notification.service";
const createNotification = catchAsync(async (req: Request, res: Response) =>
	sendResponse(res, {
		statusCode: 201,
		success: true,
		message: "Notification created successfully",
		data: await NotificationService.createNotification(req.body),
	}),
);
const getAllNotifications = catchAsync(async (req: Request, res: Response) =>
	sendResponse(res, {
		statusCode: 200,
		success: true,
		message: "Notifications retrieved successfully",
		data: await NotificationService.getAllNotifications(req.user!.userId),
	}),
);
const getSingleNotification = catchAsync(async (req: Request, res: Response) =>
	sendResponse(res, {
		statusCode: 200,
		success: true,
		message: "Notification retrieved successfully",
		data: await NotificationService.getSingleNotification(
			req.params.id as string,
			req.user!.userId,
		),
	}),
);
const updateNotification = catchAsync(async (req: Request, res: Response) =>
	sendResponse(res, {
		statusCode: 200,
		success: true,
		message: "Notification updated successfully",
		data: await NotificationService.updateNotification(
			req.params.id as string,
			req.user!.userId,
			req.body,
		),
	}),
);
const deleteNotification = catchAsync(async (req: Request, res: Response) =>
	sendResponse(res, {
		statusCode: 200,
		success: true,
		message: "Notification deleted successfully",
		data: await NotificationService.deleteNotification(
			req.params.id as string,
			req.user!.userId,
		),
	}),
);
export const NotificationController = {
	createNotification,
	getAllNotifications,
	getSingleNotification,
	updateNotification,
	deleteNotification,
};
